(r, big) => {
    const pool = big
      ? Array.from({ length: 60 }, (_, i) => String.fromCharCode(65 + (i % 26)) + String.fromCharCode(65 + Math.floor(i / 26)) + "X")
      : r.shuffle(["ICN", "ICA", "AMS", "BOS", "BOM"]).slice(0, r.int(2, 4));
    const m = big ? 20000 : r.int(1, 7);
    let cur = r.pick(pool);
    const start = cur, tickets = [];
    // a random walk is always a valid route, so the guarantee holds
    for (let i = 0; i < m; i++) { let nx; do nx = r.pick(pool); while (nx === cur); tickets.push([cur, nx]); cur = nx; }
    return [r.shuffle(tickets), start];
  }

