function planRoute(tickets: string[][], start: string): string[] {
  const out = new Map<string, string[]>();
  for (const [a, b] of tickets) {
    if (!out.has(a)) out.set(a, []);
    out.get(a)!.push(b);
  }
  const used = new Map<string, boolean[]>();
  for (const [a, list] of out) { list.sort(); used.set(a, list.map(() => false)); }
  const route = [start];
  const dfs = (): boolean => {
    if (route.length === tickets.length + 1) return true;
    const at = route[route.length - 1], list = out.get(at) ?? [], u = used.get(at) ?? [];
    for (let i = 0; i < list.length; i++) {
      if (u[i]) continue;
      u[i] = true;
      route.push(list[i]);
      if (dfs()) return true;
      route.pop();
      u[i] = false;
    }
    return false;
  };
  dfs();
  return route;
}

