function planRoute(tickets: string[][], start: string): string[] {
  const out = new Map<string, string[]>();
  for (const [a, b] of tickets) {
    if (!out.has(a)) out.set(a, []);
    out.get(a)!.push(b);
  }
  // largest first, so pop() hands out the smallest destination
  for (const list of out.values()) list.sort().reverse();
  const stack = [start], route: string[] = [];
  while (stack.length) {
    const left = out.get(stack[stack.length - 1]);
    if (left && left.length) stack.push(left.pop()!);
    else route.push(stack.pop()!);
  }
  return route.reverse();
}

