class Solution:
    def planRoute(self, tickets: List[List[str]], start: str) -> List[str]:
        out = defaultdict(list)
        # reverse-sorted, so pop() hands out the smallest destination
        for a, b in sorted(tickets, reverse=True):
            out[a].append(b)
        stack, route = [start], []
        while stack:
            if out[stack[-1]]:
                stack.append(out[stack[-1]].pop())
            else:
                route.append(stack.pop())
        return route[::-1]

